#!/usr/bin/env python3
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
def read(path: str) -> str: return (ROOT / path).read_text(encoding="utf-8")
def require(condition: bool, message: str) -> None:
    if not condition: raise SystemExit(f"FAIL: {message}")
module_types=read("src/main/kotlin/de/teutonstudio/ccaeroworks/registry/CCModuleTypes.kt"); source=read("src/main/kotlin/de/teutonstudio/ccaeroworks/input/CombinedInputSource.kt"); control=read("src/main/kotlin/de/teutonstudio/ccaeroworks/input/CombinedLeverController.kt"); controller=read("src/main/kotlin/de/teutonstudio/ccaeroworks/input/DisplayCombinedInputController.kt"); context=read("src/main/kotlin/de/teutonstudio/ccaeroworks/input/CombinedInputContext.kt"); coordinator=read("src/main/kotlin/de/teutonstudio/ccaeroworks/input/CombinedInputCoordinator.kt"); lifecycle=read("src/main/kotlin/de/teutonstudio/ccaeroworks/mixin/client/AeroworksControlSessionMixin.kt"); sample=read("src/main/kotlin/de/teutonstudio/ccaeroworks/network/CombinedControlSamplePayload.kt"); legacy=read("src/main/kotlin/de/teutonstudio/ccaeroworks/network/SetCombinedLeverValuePayload.kt"); peripheral=read("src/main/kotlin/de/teutonstudio/ccaeroworks/compat/computercraft/ControlDeskPeripheralState.kt"); override_guard=read("src/main/kotlin/de/teutonstudio/ccaeroworks/mixin/ConsoleBlockEntityControlOverrideMixin.kt"); combined_ui=read("src/main/kotlin/de/teutonstudio/ccaeroworks/mixin/client/ModuleScreenCombinedInputMixin.kt"); client=read("src/main/kotlin/de/teutonstudio/ccaeroworks/client/CCAeroworksClient.kt"); semantics=read("src/main/kotlin/de/teutonstudio/ccaeroworks/computer/channel/ControlChannelSemantics.kt"); dbw_guard=read("src/main/java/de/teutonstudio/ccaeroworks/mixin/client/DriveByWireDisplaySourceMixin.java"); catalog=read("src/main/java/de/teutonstudio/ccaeroworks/mixin/compat/ConsoleWireChannelsDisplayFilterMixin.java"); signal=read("src/main/java/de/teutonstudio/ccaeroworks/mixin/compat/DriveByWireSignalFilterMixin.java"); mixins=read("src/main/resources/cc_aeroworks.mixins.json"); workflow=read(".github/workflows/verify.yml")
require("interactive = true" in module_types and 'addClonedChannel(builder, YOKE_X_TEMPLATE, "x")' in module_types and 'addClonedChannel(builder, YOKE_Y_TEMPLATE, "y")' in module_types, "interactive displays must keep real Aeroworks x/y")
require('"cc_aeroworks:three_digit_display" to listOf(X_CHANNEL, Y_CHANNEL)' in source and '"cc_aeroworks:large_radar_display" to listOf(X_CHANNEL, Y_CHANNEL)' in source, "display pointer channel declarations missing")
require("fun isCombinedOnly(module: MountedModule): Boolean = isDisplayPointerModule(module)" in source and "forceCombined(invoker, module, column, index)" in combined_ui, "display x/y must remain Combined-only")
require("ConsoleMultiblockManager.resolve" in context and "lastSelections" in context and "cachedContext" in context, "Combined input must keep canonical cached multiblock context")
require("WATCHDOG_INTERVAL_TICKS = 5" in control and "WATCHDOG_INTERVAL_TICKS = 5" in controller and "claimControl" in control and "claimDisplay" in controller, "Combined ownership/watchdog contract changed")
require("ConsoleControlClient.isActive()" in control and "ConsoleControlClient.isActive()" in controller and 'method = ["exit(Ljava/lang/String;)V"]' in lifecycle, "Combined sessions must follow Aeroworks lifecycle")
require("desk.setChannelFromController" in sample and "previousValue" in sample and "effectiveValue" in sample and "previousValue" in legacy and "effectiveValue" in legacy, "server must keep real effective Aeroworks values")
require("ControlOverrideManager.isHardOverridden" in override_guard and "fun queueImmediateInput" in peripheral and "CombinedInputSource.activationBinding" in controller, "control authority/event/binding contract changed")
require("CombinedControlModeTracker" not in client, "obsolete mirrored Combined session tracker returned")
require("DISPLAY_POINTER" in semantics and "driveByWire = supported && kind == ControlChannelKind.VEHICLE_CONTROL" in semantics and "computerOverride = supported && kind == ControlChannelKind.VEHICLE_CONTROL" in semantics, "shared display semantics must reject DBW/vehicle override")
require("ControlChannelSemantics.INSTANCE.kind(module)" in dbw_guard, "standalone display DBW guard must use shared semantics")
require("filterExposedIds" in catalog and "ConsoleWireChannels" in catalog, "Aeroworks DBW catalogue must remove display pointer x/y")
require("getCurrentSignal" in signal and "CallbackInfoReturnable<Integer>" in signal and "cir.setReturnValue(0)" in signal, "final DBW value lookup must force display pointer signals to zero")
require("priority = 2100" in signal and "isDriveByWireExposed" in signal, "display value guard must run before lower-priority DBW integrations")
for registered in ('"client.DriveByWireDisplaySourceMixin"','"compat.ConsoleWireChannelsDisplayFilterMixin"','"compat.DriveByWireSignalFilterMixin"'): require(registered in mixins, f"missing display isolation mixin {registered}")
require((ROOT / "src/main/resources/assets/cc_aeroworks/textures/gui/combined_input_placeholder.png").is_file(), "Combined icon missing")
require("python3 tools/verify-display-combined-input.py" in workflow, "workflow must enforce display Combined contract")
print("Validated Combined display input plus source, catalogue and final DBW signal-read isolation.")
